#
# Compute subject-level network matrices (UK Biobank style) from the
# dual-regression stage-1 timeseries generated by brc_IDP_rfMRI_netmats.sh.
#
# Python port of bb_netmats.m and of the FSLNets functions it uses
# (nets_load, nets_tsclean, nets_netmats), restricted to the options used here:
#   nets_load(dir, tr, 0, 1, vols)            demean only, one run
#   nets_tsclean(ts, 1)                       aggressive removal of the noise components
#   nets_netmats(ts, -r2zFULL, 'corr')        full correlation, r-to-z with a fixed factor
#   nets_netmats(ts, -r2zPARTIAL, 'ridgep', 0.5)  ridge partial correlation, r-to-z with a fixed factor
#
# Usage: brc_IDP_netmats.py <netmats_dir>
#
# <netmats_dir> must contain rfMRI_25.dr/dr_stage1.txt and rfMRI_100.dr/dr_stage1.txt
# Outputs (one line each, written to <netmats_dir>):
#   rfMRI_d{25,100}_NodeAmplitudes_v1.txt
#   rfMRI_d{25,100}_fullcorr_v1.txt
#   rfMRI_d{25,100}_partialcorr_v1.txt

import os
import sys

import numpy as np


# Noise (removed) components (1-based, as in the MATLAB code) and r-to-z scaling factors
SETTINGS = {
    '25':  {'noise': [4, 23, 24, 25],
            'r2zFULL': 10.6484,
            'r2zPARTIAL': 10.6707},
    '100': {'noise': [1, 44, 47, 51, 54, 55, 56, 59, 61, 62] + list(range(65, 93)) + list(range(94, 101)),
            'r2zFULL': 19.7177,
            'r2zPARTIAL': 18.8310},
}

RIDGE_RHO = 0.5


def matlab_pinv(a):
    # Same singular value cut-off as MATLAB's pinv: max(size(A)) * norm(A) * eps
    return np.linalg.pinv(a, rcond=max(a.shape) * np.finfo(float).eps)


def load_ts(ts_file):
    # nets_load with varnorm=0: demean each timeseries
    ts = np.loadtxt(ts_file, ndmin=2)
    return ts - ts.mean(axis=0)


def clean_ts(ts, good, bad):
    # nets_tsclean with aggressive=1: regress the noise timeseries out of the good ones
    good_ts = ts[:, good]
    bad_ts = ts[:, bad]
    return good_ts - bad_ts @ (matlab_pinv(bad_ts) @ good_ts)


def r2z(r, factor):
    # nets_netmats with do_rtoz<0
    return 0.5 * np.log((1 + r) / (1 - r)) * factor


def full_corr(ts, factor):
    # nets_netmats 'corr'
    n = ts.shape[1]
    grot = np.corrcoef(ts, rowvar=False)
    grot[np.eye(n) > 0] = 0
    return r2z(grot, factor)


def ridge_partial_corr(ts, factor, rho):
    # nets_netmats 'ridgep'
    n = ts.shape[1]
    grot = np.cov(ts, rowvar=False)
    grot = grot / np.sqrt(np.mean(np.diag(grot) ** 2))
    grot = -np.linalg.inv(grot + rho * np.eye(n))
    d = np.sqrt(np.abs(np.diag(grot)))
    grot = grot / d[:, None] / d[None, :]
    grot[np.eye(n) > 0] = 0
    return r2z(grot, factor)


def upper_triangle(mat):
    # MATLAB grot(triu(ones(N),1)==1): upper triangle in column-major order
    mask = np.triu(np.ones(mat.shape, dtype=bool), 1)
    return mat.flatten(order='F')[mask.flatten(order='F')]


def write_line(path, values):
    # MATLAB num2str(x, '%14.8f'): fixed-width values with leading blanks removed
    line = ''.join('%14.8f' % v for v in values).strip()
    with open(path, 'w') as f:
        f.write(line + '\n')


def main():
    if len(sys.argv) != 2:
        sys.stderr.write('Usage: %s <netmats_dir>\n' % os.path.basename(sys.argv[0]))
        sys.exit(1)

    netmats_dir = sys.argv[1]

    for D in ['25', '100']:
        ts_file = os.path.join(netmats_dir, 'rfMRI_%s.dr' % D, 'dr_stage1.txt')
        if not os.path.isfile(ts_file):
            sys.stderr.write('brc_IDP_netmats: missing %s\n' % ts_file)
            sys.exit(1)

        ts = load_ts(ts_file)

        n_comp = int(D)
        if ts.shape[1] != n_comp:
            sys.stderr.write('brc_IDP_netmats: expected %d timeseries in %s, found %d\n' % (n_comp, ts_file, ts.shape[1]))
            sys.exit(1)

        noise = [i - 1 for i in SETTINGS[D]['noise']]
        good = [i for i in range(n_comp) if i not in noise]

        ts = clean_ts(ts, good, noise)

        netmat_full = full_corr(ts, SETTINGS[D]['r2zFULL'])
        netmat_partial = ridge_partial_corr(ts, SETTINGS[D]['r2zPARTIAL'], RIDGE_RHO)

        write_line(os.path.join(netmats_dir, 'rfMRI_d%s_fullcorr_v1.txt' % D), upper_triangle(netmat_full))
        write_line(os.path.join(netmats_dir, 'rfMRI_d%s_partialcorr_v1.txt' % D), upper_triangle(netmat_partial))
        write_line(os.path.join(netmats_dir, 'rfMRI_d%s_NodeAmplitudes_v1.txt' % D), np.std(ts, axis=0, ddof=1))


if __name__ == '__main__':
    main()
